'use strict';
const $=id=>document.getElementById(id);
let state=null, csrf='', lastSeq=0, source=null, reasonBlocks=new Map(), replyBlocks=new Map(), toastTimer;
const labels={preference:'偏好与习惯',experience:'共同经历',relationship:'关系与约定',project:'正在做的事',correction:'纠正记录',interest:'兴趣'};
const events={'console.start':'控制台启动','owner.message':'主人留言已保存','memory.saved':'保存长期记忆','control.pause':'暂停活动','control.correct':'收到纠正，已暂停','control.resume':'主人允许继续','approval.decided':'安装申请已有决定','export.saved':'记录已导出','turn.start':'助手开始回应','turn.end':'本轮结束','runtime.error':'连接出现问题','tool.start':'开始操作','tool.end':'操作结果'};
Object.assign(events,{'task.accepted':'她已收到消息','task.result':'本轮处理结果','control.hold':'活动已暂停','correction.acknowledged':'她已说明纠正后的理解','budget.settled':'费用已记录','desktop.connected':'专属桌面已连接','desktop.disconnected':'专属桌面暂时离线'});
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6500);}
function stamp(t){return new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});}
async function post(path,body={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Error(v.error||'操作未完成');return v;}
async function refresh(){try{const r=await fetch('/api/status');if(!r.ok)throw Error('状态不可用');state=await r.json();csrf=state.csrf;renderStatus();renderApprovals();}catch(e){$('connection').textContent='连接中断，记录仍在本地';$('liveDot').className='';}}
function renderStatus(){const s=state;$('version').textContent='本地空间 · v'+s.version;$('state').textContent=s.blockers.length?'基础设施准备中':s.paused?'自主活动已暂停':'等待电脑空闲';$('stateHint').textContent=s.blockers.length?s.blockers[0]:'你随时可以暂停或纠正';$('desktopBadge').textContent=s.desktop.ready?'已连接':'待接入';$('desktopEmpty').hidden=s.desktop.ready;$('desktopFrame').hidden=!s.desktop.ready;if(s.desktop.ready)$('desktopFrame').src='/api/frame?t='+Date.now();$('persona').textContent=s.persona.available?s.persona.version.replace('-two-personas-draft',' · 草稿'):'来源待确认';$('personaHint').textContent=s.persona.available?'默认'+s.persona.default+'人格 · 已核对来源，尚未载入':'请检查人格入口';$('memoryCount').textContent=s.memory_count;$('cost').textContent='¥ '+s.budget.local_recorded_cny.toFixed(2)+' / 20';$('costHint').textContent=s.budget.shared_ledger_verified?'19.5 元暂停，次日按账本恢复':'共享账本待核实 · 付费调用关闭';$('storage').textContent=s.storage.used_bytes<2**20?Math.ceil(s.storage.used_bytes/1024)+' KB':(s.storage.used_bytes/2**20).toFixed(1)+' MB';$('free').textContent='磁盘剩余 '+(s.storage.free_bytes/2**30).toFixed(1)+' GB · 至少保留50GB';$('resource').textContent=s.resources.known?'电脑空闲 '+Math.floor(s.resources.idle_seconds/60)+' 分钟 · 可用内存 '+s.resources.available_ram_gb+' GB':'暂不能确认电脑空闲状态';$('reasonModel').textContent='DeepSeek Flash · '+(s.reasoning_stream_seen?'已收到模型思考原文':'待连接');$('correctionState').textContent=s.correction?(s.correction_ack_revision===s.revision?'助手已说明新理解；仍需你允许继续':'已暂停，等待助手说明纠正后的理解和下一步'):'纠正后，等她说明新理解，再由你允许继续。';$('resume').title=s.blockers.join('；');}
function renderApprovals(){const box=$('approvalList');box.replaceChildren();$('requestCount').textContent=state.approvals.filter(x=>x.status==='pending').length;for(const a of state.approvals){const card=el('article',undefined,'approval'),heading=el('div',undefined,'approval-heading');heading.append(el('h3',a.title),el('span',({pending:'待你决定',approved:'已允许，尚未执行',denied:'已拒绝'})[a.status],'pill'));card.append(heading);const dl=el('dl');for(const [key,label]of [['purpose','用途'],['source','来源'],['version','版本'],['download','下载量'],['disk','空间'],['scope','范围'],['license','授权']]){if(a.details[key]){dl.append(el('dt',label));const dd=el('dd');if(key==='source'){const link=el('a',a.details[key]);try{const u=new URL(a.details[key]);if(u.protocol==='https:'){link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';dd.append(link);}else dd.textContent=a.details[key];}catch{dd.textContent=a.details[key];}}else dd.textContent=a.details[key];dl.append(dd);}}card.append(dl);card.append(el('p','允许只保存决定；不会在你的日常系统里安装，也不会自动购买授权。','muted'));if(a.status==='pending'){const acts=el('div',undefined,'approval-actions');for(const [decision,label]of [['approved','允许准备这项安装'],['denied','暂不允许']]){const b=el('button',label,decision==='approved'?'primary':'');b.onclick=async()=>{b.disabled=true;try{await post('/api/control/approval',{id:a.id,decision});await refresh();toast(decision==='approved'?'已保存允许；等待安装执行条件核实':'已保存，保持暂停');}catch(e){toast(e.message);b.disabled=false;}};acts.append(b);}card.append(acts);}box.append(card);}if(!state.approvals.length)box.append(el('p','目前没有待决定的申请。','empty'));}
async function loadMemories(){try{const r=await fetch('/api/memory?q='+encodeURIComponent($('search').value));const rows=await r.json(),box=$('memoryList');box.replaceChildren();for(const m of rows){const row=el('div',undefined,'memory-row');row.append(el('span',labels[m.kind]||m.kind,'tag'),el('p',m.text),el('small',(m.source==='owner'?'你保存的':'助手记录')+' · '+stamp(m.time)));box.append(row);}if(!rows.length)box.append(el('p',$('search').value?'没有找到相关记忆。':'还没有正式经历。旧试验记录不会自动成为她的记忆。','empty'));}catch(e){toast('记忆读取失败，请稍后重试');}}
function addMessage(text,role,status){const box=$('messages');box.querySelector('.welcome')?.remove();const m=el('div',undefined,'message '+role),p=el('p',text);m.append(p);if(status)m.append(el('small',status));box.append(m);box.scrollTop=box.scrollHeight;return p;}
function onEvent(e){if(e.seq<=lastSeq)return;lastSeq=e.seq;const p=e.payload;if(e.kind==='reasoning.delta'){const key=e.task_id||p.message_id||'current';let block=reasonBlocks.get(key);if(!block){if(!reasonBlocks.size)$('reasonText').replaceChildren();block=el('div',undefined,'reason-block');block.append(el('small',stamp(e.time)+' · Flash · 模型返回原文'),el('span',''));$('reasonText').append(block);reasonBlocks.set(key,block.lastChild);}block.textContent+=p.text;$('reasonText').scrollTop=$('reasonText').scrollHeight;return;}if(e.kind==='reply.delta'){const key=e.task_id||p.message_id||'current';let block=replyBlocks.get(key);if(!block){block=addMessage('','assistant','模型回复原文');replyBlocks.set(key,block);}block.textContent+=p.text;return;}if(e.kind==='owner.message')addMessage(p.text,'user','已保存 · 等待专属助手接通');const row=el('div',undefined,'event-row');row.append(el('time',stamp(e.time)));const t=el('div');t.append(el('p',events[e.kind]||e.kind),el('small',p.message||p.filename||p.text||p.decision||''));row.append(t);$('eventList').prepend(row);while($('eventList').children.length>150)$('eventList').lastChild.remove();if(e.kind==='memory.saved')loadMemories();}
function connect(){source=new EventSource('/api/events?after='+lastSeq);source.onopen=()=>{$('connection').textContent='本地控制台已连接';$('liveDot').className='live';};source.onmessage=e=>{try{onEvent(JSON.parse(e.data));}catch{toast('有一条事件格式异常，记录仍保留在本地');}};source.onerror=()=>{$('connection').textContent='正在重新连接';$('liveDot').className='';};}
async function guardedForm(event,work){event.preventDefault();const b=event.target.querySelector('button');b.disabled=true;try{await work();await refresh();}catch(e){toast(e.message);}finally{b.disabled=false;}}
$('chatForm').onsubmit=e=>guardedForm(e,async()=>{const key=$('chatForm').dataset.key||crypto.randomUUID();$('chatForm').dataset.key=key;await post('/api/control/chat',{text:$('chat').value,request_key:key});$('chat').value='';delete $('chatForm').dataset.key;toast('留言已保存；专属执行器尚未接通，当前不会开始操作。');});
$('chat').oninput=()=>delete $('chatForm').dataset.key;
$('memoryForm').onsubmit=e=>guardedForm(e,async()=>{await post('/api/memory',{kind:$('memoryKind').value,text:$('memoryText').value});$('memoryText').value='';await loadMemories();toast('记忆已保存');});
$('correctionForm').onsubmit=e=>guardedForm(e,async()=>{await post('/api/control/correct',{text:$('correction').value});$('correction').value='';toast('纠正已留档，活动保持暂停。');});
for(const action of ['pause','resume'])$(action).onclick=async()=>{try{await post('/api/control/'+action);await refresh();toast(action==='pause'?'已暂停；新的动作不会领取':'已允许继续');}catch(e){toast(e.message);}};
$('export').onclick=async()=>{try{const v=await post('/api/export');const a=el('a');a.href=v.url;a.download='';document.body.append(a);a.click();a.remove();toast('已导出，含记忆、记录和校验清单。');}catch(e){toast(e.message);}};
$('search').oninput=loadMemories;
$('reasonClose').onclick=()=>{$('reasonWindow').hidden=true;localStorage.setItem('reasonHidden','1');};$('reasonToggle').onclick=()=>{$('reasonWindow').hidden=false;localStorage.removeItem('reasonHidden');};
if(localStorage.getItem('reasonHidden'))$('reasonWindow').hidden=true;
let drag=null;const win=$('reasonWindow'),handle=$('reasonHandle');handle.onpointerdown=e=>{if(e.target.closest('button'))return;const r=win.getBoundingClientRect();drag={dx:e.clientX-r.left,dy:e.clientY-r.top};handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(!drag)return;win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,e.clientX-drag.dx))+'px';win.style.top=Math.max(0,Math.min(innerHeight-50,e.clientY-drag.dy))+'px';win.style.right='auto';win.style.bottom='auto';};handle.onpointerup=()=>{drag=null;};
addEventListener('resize',()=>{if(win.style.left){win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,parseFloat(win.style.left)))+'px';win.style.top=Math.max(0,Math.min(innerHeight-50,parseFloat(win.style.top)||0))+'px';}});
let thinkingSeq=0,thinkingSource=null;
function connectThinking(){
 if(!state?.runtime.session_id)return;
 thinkingSource=new EventSource('/api/thinking/stream?after='+thinkingSeq);
 const render=event=>{try{
  const v=JSON.parse(event.data);if(v.sessionId!==state.runtime.session_id)return;
  if(v.kind==='reasoning.delta'||v.kind==='reasoning.snapshot'){
   if(v.seq<=thinkingSeq)return;thinkingSeq=v.seq;
   const key=v.attemptId+':'+(v.blockIndex??0);let block=reasonBlocks.get(key);
   if(!block){if(!reasonBlocks.size)$('reasonText').replaceChildren();const card=el('div',undefined,'reason-block');card.append(el('small',stamp(v.time||v.receivedAt)+' · '+(v.origin==='native-live'?'实时原文':'历史回填')),el('span',''));$('reasonText').append(card);block=card.lastChild;reasonBlocks.set(key,block);}
   if(v.kind==='reasoning.snapshot')block.textContent=v.text;else block.textContent+=v.text;
   $('reasonModel').textContent='DeepSeek Flash · '+(v.origin==='native-live'?'正在实时接收':'历史原文回填');
   $('reasonText').scrollTop=$('reasonText').scrollHeight;
  }
 }catch{toast('思考接口有一条格式异常，未补写内容');}};
 thinkingSource.onmessage=render;thinkingSource.addEventListener('reasoning',render);
 thinkingSource.onerror=()=>{$('reasonModel').textContent='DeepSeek Flash · 等待思考接口恢复';};
}
const originalEvent=onEvent;
onEvent=function(e){
 if(e.kind==='task.result'&&e.seq>lastSeq&&e.payload.text)addMessage(e.payload.text,'assistant',e.payload.status==='completed'?'本轮已完成':'本轮已停止');
 originalEvent(e);
};
const originalStatus=renderStatus;
renderStatus=function(){originalStatus();if(state.runtime.chat_ready){$('state').textContent=state.desktop.ready?'Flash 与长期记忆已连接':'Flash 与长期记忆已连接 · 桌面准备中';$('stateHint').textContent=state.paused?'自主活动暂停，仍可与她交流':'等待电脑空闲';$('chatForm').querySelector('button').textContent='发送给她 ↑';$('personaHint').textContent=state.persona.loaded_into_runtime?'默认'+state.persona.default+'人格 · 已载入当前版本':'当前载入 '+(state.persona.active_version||'未知')+'，有新草案待确认';$('costHint').textContent='本空间峰值保守估算 · 19.5元停止';const actual=state.thinking?.model||state.model;$('reasonModel').textContent=(actual==='deepseek-flash'?'Flash 1017':actual)+' · '+(state.thinking?.canObserve?'实时采集已连接':'等待思考接口恢复');}};
$('chatForm').onsubmit=e=>guardedForm(e,async()=>{const key=$('chatForm').dataset.key||crypto.randomUUID();$('chatForm').dataset.key=key;await post('/api/control/chat',{text:$('chat').value,request_key:key});$('chat').value='';delete $('chatForm').dataset.key;toast(state.runtime.chat_ready?'消息已保存，正在交给她处理':'留言已保存，等待专属助手接通');});
refresh().then(()=>{loadMemories();connect();connectThinking();});setInterval(refresh,5000);
